def log_trace(rider_id, action, details):
    session = SessionLocal()
    trace = Trace(rider_id=rider_id, action=action, details=json.dumps(details), timestamp=datetime.utcnow())
    session.add(trace)
    session.commit()
    session.close()


def fetch_trips(rider_id: str, date: str = None) -> str:
    """Fetch trips for a rider, optionally filtered by date (YYYY-MM-DD)."""
    session = SessionLocal()
    query = session.query(Trip).filter(Trip.rider_id == rider_id)
    if date:
        query = query.filter(Trip.started_at.like(f"{date}%"))
    trips = query.order_by(Trip.started_at.desc()).limit(30).all()
    session.close()
    return json.dumps([{"trip_id": t.trip_id, "started_at": t.started_at, "status": t.status, "distance_km": t.distance_km, "surge_multiplier": t.surge_multiplier} for t in trips])


